        private Dictionary<string, string> getAtrs(
          List<string> langs,
          int projID,
          PDAPIManager PDAPImgr)
        {
            Dictionary<string, string> atrs = new Dictionary<string, string>();
            List<PDProjectCustomAttribute> result = PDAPImgr.GetCustomAttributesByProjectID(projID).Result;
            if (result != null)
            {
                Dictionary<string, string> dictionary = new Dictionary<string, string>();
                string empty = string.Empty;
                List<string> stringList = new List<string>();
                foreach (string lang in langs)
                {
                    string pdLocale = this.ConvertLocaleToPDLocale(lang, this.config.LocaleMap);
                    stringList.Add(pdLocale.Replace("-", ""));
                    if (result.Where<PDProjectCustomAttribute>((Func<PDProjectCustomAttribute, bool>)(a => a.name.Equals(pdLocale.Replace("-", "")))).ToList<PDProjectCustomAttribute>().Count<PDProjectCustomAttribute>() != 0)
                        atrs.Add(lang, "true");
                    else
                        atrs.Add(lang, "false");
                }
                foreach (PDProjectCustomAttribute projectCustomAttribute in result)
                {
                    string name = projectCustomAttribute.name;
                    if (!stringList.Contains(name))
                    {
                        if (projectCustomAttribute.values != null)
                            atrs.Add(projectCustomAttribute.name, string.Join(",", projectCustomAttribute.values.ToArray()));
                        else
                            atrs.Add(projectCustomAttribute.name, (string)null);
                    }
                }
            }
            return atrs;
        }

        private string ConvertLocaleToPDLocale(string sitecoreLocale, string localeMap)
        {
            string str1 = localeMap;
            char[] chArray = new char[1] { ',' };
            foreach (string str2 in str1.Split(chArray))
            {
                string[] strArray = str2.Trim().Split(':');
                if (strArray[0].Equals(sitecoreLocale))
                    return strArray[1];
            }
            return sitecoreLocale;
        }

