            string[] strArray = pShortCode_pID.Split('_');
            switch (whatToReturn)
            {
                case "pShortCode":
                    ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: pShortCode_pIDSplit - Returning pShortCode: " + strArray[0]));
                    return strArray[0];
