                    ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: pShortCode_pIDSplit - Returning pID: " + strArray[1]));
                    return strArray[1];
                default:
                    ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: pShortCode_pIDSplit - Something went wrong."));
                    return "";
            }
        }

