        private void processGuid(
          string guid,
          string itemToTranslateID,
          string pLayer,
          Language language)
        {
            if (string.IsNullOrEmpty(guid))
            {
                ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: item is null, moving on."));
            }
            else
            {
                ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: First item is: " + guid));
                Item key = this.master.GetItem(new ID(guid), language);
                if (!this.allItemGuidsToTranslate.Contains(key.ID.ToString()) && !key.Versions.Equals((object)0))
                {
                    ILog logger1 = ExportSupportForm.logger;
                    int managedThreadId = Thread.CurrentThread.ManagedThreadId;
                    string message1 = managedThreadId.ToString() + " ExportSupportForm: Adding to the list";
                    logger1.Debug((object)message1);
                    this.allItemsToTranslate.Add(new KeyValuePair<Item, string>(key, itemToTranslateID));
                    this.allItemGuidsToTranslate.Add(key.ID.ToString());
                    if (!this.allParentItemsToTranslate.Keys.Contains<string>(guid))
                        this.allParentItemsToTranslate.Add(guid, new List<string>());
                    if (string.IsNullOrEmpty(pLayer))
                        return;
                    ILog logger2 = ExportSupportForm.logger;
                    managedThreadId = Thread.CurrentThread.ManagedThreadId;
                    string message2 = managedThreadId.ToString() + " ExportSupportForm: Getting presentation layer controls";
                    logger2.Debug((object)message2);
                    this.getPresentationItems(key, guid);
                }
                else
                    ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: This list item is already queued. Moving on to the next one."));
            }
        }

        private List<string> GetTranslatableFields(string templateID)
        {
            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: Now getting the translatable fields for template ID: " + templateID));
            List<string> translatableFields = new List<string>();
            if (ExportSupportForm.db_type.Equals("sql"))
            {
                using (SqlConnection sqlConnection = new SqlConnection(ExportSupportForm.connectionString))
                {
                    sqlConnection.Open();
                    using (SqlCommand command = sqlConnection.CreateCommand())
                    {
                        command.CommandText = "SELECT * from GlobalLink_TranslatableFields where TemplateID=@tid";
                        command.Parameters.AddWithValue("@tid", (object)templateID);
                        using (SqlDataReader sqlDataReader = command.ExecuteReader())
                        {
                            while (sqlDataReader.Read())
                            {
                                string str = sqlDataReader.GetString(sqlDataReader.GetOrdinal("FieldID"));
                                translatableFields.Add(str);
                            }
                        }
                    }
                }
            }
            else
            {
                using (OracleConnection oracleConnection = new OracleConnection(ExportSupportForm.connectionString))
                {
                    oracleConnection.Open();
                    using (OracleCommand command = oracleConnection.CreateCommand())
                    {
                        command.CommandText = "SELECT * from GlobalLink_TranslatableFields where TemplateID=:tid";
                        command.Parameters.Clear();
                        command.Parameters.Add(new OracleParameter("tid", (object)templateID));
                        using (OracleDataReader oracleDataReader = command.ExecuteReader())
                        {
                            while (oracleDataReader.Read())
                            {
                                string str = oracleDataReader.GetString(oracleDataReader.GetOrdinal("FieldID"));
                                translatableFields.Add(str);
                            }
                        }
                    }
                }
            }
            return translatableFields;
        }

