        protected string getPDSourceLocale(string sourceLocaleMap, string currentItemSourceLocale)
        {
            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: getPDSourceLocale - Get the PD Source locale for the current page locale, which is: " + currentItemSourceLocale));
            if (!string.IsNullOrEmpty(sourceLocaleMap))
            {
                string str1 = sourceLocaleMap;
                char[] chArray1 = new char[1] { ',' };
                foreach (string str2 in str1.Split(chArray1))
                {
                    char[] chArray2 = new char[1] { ':' };
                    string[] strArray = str2.Split(chArray2);
                    if (currentItemSourceLocale.Equals(strArray[0].Trim()))
                    {
                        ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: getPDSourceLocale - Returning: " + strArray[1].Trim()));
                        return strArray[1].Trim();
                    }
                }
            }
            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: getPDSourceLocale - Could not find a match in the map, so we will return the same locale"));
            return currentItemSourceLocale;
        }

        protected List<string> GetTranslatableTemplates()
        {
            List<string> translatableTemplates = new List<string>();
            if (ExportSupportForm.db_type.Equals("sql"))
            {
                using (SqlConnection sqlConnection = new SqlConnection(ExportSupportForm.connectionString))
                {
                    sqlConnection.Open();
                    using (SqlCommand command = sqlConnection.CreateCommand())
                    {
                        command.CommandText = "select distinct TemplateID from GlobalLink_TranslatableFields";
                        using (SqlDataReader sqlDataReader = command.ExecuteReader())
                        {
                            while (sqlDataReader.Read())
                                translatableTemplates.Add(sqlDataReader.GetValue(0).ToString());
                        }
                    }
                    sqlConnection.Close();
                }
            }
            else
            {
                using (OracleConnection oracleConnection = new OracleConnection(ExportSupportForm.connectionString))
                {
                    oracleConnection.Open();
                    using (OracleCommand command = oracleConnection.CreateCommand())
                    {
                        command.CommandText = "select distinct TemplateID from GlobalLink_TranslatableFields";
                        using (OracleDataReader oracleDataReader = command.ExecuteReader())
                        {
                            while (oracleDataReader.Read())
                                translatableTemplates.Add(oracleDataReader.GetValue(0).ToString());
                        }
                    }
                    oracleConnection.Close();
                }
            }
            return translatableTemplates;
        }

        protected void fillProjectDictionary(
          string sourceLocale,
          string contentPath,
          PDAPIManager PDAPImgr)
        {
            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: Now in fillProjectDictionary with content path = " + contentPath));
            string pdSourceLocale = this.getPDSourceLocale(this.config.LocaleMap, sourceLocale);
            bool flag1 = false;
            ArrayList arrayList = new ArrayList();
            string contentPathToProject = this.config.ContentPathToProject;
            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: The property map is " + contentPathToProject + " and the checkbox value is: " + this.config.EnableContentPathMapping.ToString()));
            if (this.config.EnableContentPathMapping && !string.IsNullOrEmpty(contentPathToProject) && contentPath.ToLower().StartsWith("/sitecore/content"))
            {
                string str1 = contentPathToProject;
                char[] chArray1 = new char[1] { '|' };
                foreach (string str2 in str1.Split(chArray1))
                {
                    char[] chArray2 = new char[1] { ':' };
                    string[] strArray = str2.Split(chArray2);
                    ExportSupportForm.logger.Info((object)("The content path is: " + contentPath + " propertyPath is: " + strArray[0]));
                    if (contentPath.ToLower().StartsWith(strArray[0].ToLower() + "/") || contentPath.ToLower().EndsWith(strArray[0].ToLower()))
                    {
                        flag1 = true;
                        arrayList.AddRange((ICollection)strArray[1].Split(','));
                        break;
                    }
                }
            }
            this.projects = PDAPImgr.GetProjectsFromPD().Result;
            this.projectNames = new SortedDictionary<string, string>();
            try
            {
                List<string> values = new List<string>();
                bool flag2 = true;
                int managedThreadId;
                if (this.config.EnableUserProjectRestrictions)
                {
                    string name = AuthenticationManager.GetActiveUser().Name;
                    ILog logger1 = ExportSupportForm.logger;
                    managedThreadId = Thread.CurrentThread.ManagedThreadId;
                    string message1 = managedThreadId.ToString() + " ExportSupportForm: User project restrictions is enabled. Getting projects list for current user: " + name;
                    logger1.Debug((object)message1);
                    if (this.config.UserProjectRestrictions.ContainsKey(name))
                    {
                        values = this.config.UserProjectRestrictions[name];
                        ILog logger2 = ExportSupportForm.logger;
                        managedThreadId = Thread.CurrentThread.ManagedThreadId;
                        string message2 = managedThreadId.ToString() + " ExportSupportForm: User projects: " + string.Join(", ", (IEnumerable<string>)values);
                        logger2.Debug((object)message2);
                    }
                    else
                    {
                        ILog logger3 = ExportSupportForm.logger;
                        managedThreadId = Thread.CurrentThread.ManagedThreadId;
                        string message3 = managedThreadId.ToString() + " ExportSupportForm: No projects available for user " + name;
                        logger3.Debug((object)message3);
                        flag2 = false;
                    }
                }
                if (!flag2)
                    return;
                foreach (PDProject project in this.projects)
                {
                    if (this.config.EnableUserProjectRestrictions)
                    {
                        ILog logger4 = ExportSupportForm.logger;
                        managedThreadId = Thread.CurrentThread.ManagedThreadId;
                        string message4 = managedThreadId.ToString() + " ExportSupportForm: Checking if project: " + project.shortcode + " is restricted for user";
                        logger4.Debug((object)message4);
