        protected bool isSourceLocaleInProject(PDProject project, string pdSourceLocale)
        {
            foreach (PDLanguageDirection languageDirection in project.languageDirections)
            {
                if (languageDirection.sourceLanguage.Equals(pdSourceLocale))
                    return true;
            }
            return false;
        }

        private bool areAvailableProjectsForUser() => this.config.UserProjectRestrictions.ContainsKey(AuthenticationManager.GetActiveUser().Name);

        public PDAPIManager initializePDAPIManager()
        {
            PDAPIManager pdapiManager = (PDAPIManager)null;
            try
            {
                ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: Initializing PDAPImgr"));
                PDConfig pdConfig = new PDConfig();
                pdConfig.url = this.config.PDUrl;
                pdConfig.username = this.config.PDUser;
                pdConfig.password = this.config.PDPassword;
                pdConfig.authUsername = this.config.PDAuthUser;
                pdConfig.authPassword = this.config.PDAuthPassword;
                if (!string.IsNullOrEmpty(this.config.PDProxy) && !string.IsNullOrEmpty(this.config.PDPort))
                {
                    PDProxyConfig pdProxyConfig = new PDProxyConfig();
                    pdProxyConfig.proxyHost = this.config.PDProxy;
                    pdProxyConfig.proxyPort = System.Convert.ToInt32(this.config.PDPort);
                    if (!string.IsNullOrEmpty(this.config.PDProxyUser) && !string.IsNullOrEmpty(this.config.PDProxyPassword))
                    {
                        pdProxyConfig.proxyUser = this.config.PDProxyUser;
                        pdProxyConfig.proxyPassword = this.config.PDProxyPassword;
                    }
                    pdConfig.proxy = pdProxyConfig;
                }
                pdapiManager = new PDAPIManager(pdConfig);
            }
            catch (Exception ex)
            {
                ExportSupportForm.logger.Error((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: PD Client not created due to the following exception: " + ex.Message));
                Context.ClientPage.ClientResponse.Alert("Could not connect to Project Director for the following reason: " + ex.Message);
            }
            return pdapiManager;
        }

