        private void addChildren(Item item, string itemId)
        {
            if (this.config.WLTemplateIDs.Contains(item.TemplateID.ToString()))
            {
                ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: template of item " + item.ID.ToString() + " is whitelisted. Not getting children"));
            }
            else
            {
                ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: Checking children items of the item: " + item.ID.ToString()));
                foreach (Item child in item.Children)
                {
                    ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: The child is: " + child.ID.ToString()));
                    if (!this.allItemGuidsToTranslate.Contains(child.ID.ToString()) && !child.Versions.Equals((object)0))
                    {
                        ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: Adding the child item to the list of items."));
                        this.allItemsToTranslate.Add(new KeyValuePair<Item, string>(child, itemId));
                        this.allItemGuidsToTranslate.Add(child.ID.ToString());
                        if (!this.allParentItemsToTranslate.Keys.Contains<string>(itemId))
                            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: Parent item of child not added"));
                        else if (this.allParentItemsToTranslate[itemId].Contains(child.ID.ToString()))
                            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: child item: " + child.ID.ToString() + " already added to presentation layer items of " + itemId));
                        else
                            this.allParentItemsToTranslate[itemId].Add(child.ID.ToString());
                        if (this.config.WLTemplateIDs.Contains(child.TemplateID.ToString()))
                        {
                            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: template of child item " + child.ID.ToString() + " is whitelisted. moving on."));
                        }
                        else
                        {
                            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: Checking presentation items of the child item."));
                            this.getPresentationItems(child, child.ID.ToString());
                            ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: Checking children items of the child item."));
                            this.addChildren(child, itemId);
                        }
                    }
                    else
                        ExportSupportForm.logger.Debug((object)(Thread.CurrentThread.ManagedThreadId.ToString() + " ExportSupportForm: The child item has already been included."));
                }
            }
        }
